mapper.update:
UPDATE appointments
SET appointment_status = #{toStatus},
    updated_at = CURRENT_TIMESTAMP
WHERE appointment_id = #{appointmentId}
  AND appointment_status = #{fromStatus}
  AND deleted_at IS NULL

mapper.sql:
a.deleted_at IS NULL
AND ei.deleted_at IS NULL
AND host.deleted_at IS NULL
AND a.appointment_status <> 'PAYMENT_PENDING'

    AND a.item_id = #{request.itemId}


    AND ei.item_type = #{request.itemType}


    AND a.language_code = #{request.language}


    AND (
        a.appointment_name LIKE CONCAT('%', #{request.keyword}, '%')
        OR a.appointment_description LIKE CONCAT('%', #{request.keyword}, '%')
        OR a.meeting_place LIKE CONCAT('%', #{request.keyword}, '%')
    )



        AND a.appointment_status = #{request.status}



        AND a.appointment_status <> 'COMPLETED'

mapper.select:
SELECT
FROM appointments a JOIN explore_items ei ON ei.item_id = a.item_id JOIN members host ON host.member_id = a.host_member_id WHERE
ORDER BY a.activity_start_at ASC, a.appointment_id DESC LIMIT #{request.size} OFFSET #{offset}
